insert into public.nutrition_references (citation_key,title,authors,publication_year,publication,source_url,geography,species,source_kind,evidence_scope,key_findings,limitations,reviewed,source_status,citation_notes) values ('AVIAGEN-ROSS-NUTRITION-2022','Ross Broiler Nutrition Specifications','Aviagen',2022,'Technical nutrition guide','https://eu.aviagen.com/assets/Tech_Center/Ross_Broiler/Ross-BroilerNutritionSpecifications2022-EN.pdf','International',ARRAY['broiler']::text[],'official_guide','Guide nutritionnel Ross, poulets as-hatched, table 3, poids vif cible >3,5 kg.','AMEn, protéines, acides aminés digestibles, calcium et phosphore disponible par phase.','Valeurs spécifiques au scénario de poids cible de la table 3; adapter aux conditions et au poids d''abattage.',true,'source_checked','Table officielle consultée.'),
('COBB-500-PERFORMANCE-NUTRITION-2022','Cobb 500 Broiler Performance & Nutrition Supplement','Cobb-Vantress',2022,'Performance & Nutrition Supplement','https://cobbgenetics.tz/assets/Cobb-Files/2022-Cobb500-Broiler-Performance-Nutrition-Supplement.pdf','International',ARRAY['broiler']::text[],'official_guide','Niveaux recommandés pour poulets Cobb 500 de marché moyen/grand, phases 0–12, 13–28, 29–39, 40–49 et >50 jours.','AMEn, protéines brutes, acides aminés digestibles, calcium et phosphore disponible.','Référentiel spécifique Cobb 500; ne pas transférer automatiquement aux poulets locaux.',true,'source_checked','Table officielle consultée; acides aminés exprimés en digestibles.'),
('HYLINE-BROWN-COMMERCIAL-2024','Hy-Line Brown Commercial Layers – International Standards','Hy-Line International',2024,'Performance Guide, January 2024','https://www.hylinesa.co.za/sitepad-data/uploads/2025/04/HL-Brown-Commercial-Layers-Jan-2024.pdf','International',ARRAY['layers']::text[],'official_guide','Guide commercial Hy-Line Brown; besoins journaliers par phase de production et concentrations selon ingestion journalière.','Apports journaliers d''énergie et d''acides aminés SID/total; consommation de référence.','Les besoins journaliers dépendent de l''ingestion réelle, du poids, de la masse d''œufs et de la température.',true,'source_checked','Pour les lignes SID/total, les premières valeurs correspondent au SID; la consommation réelle doit être saisie.'),
('DANBRED-WEANER-NUTRITION','Weaners – Pigs from 7–30 kg','DanBred',null,'DanBred Pig Manual','https://danbred-manual.com/en/pig-finisher-manual/weaners-pigs-from-7-30-kg/','International',ARRAY['pigs']::text[],'official_guide','Besoins par kg d''aliment pour porcs DanBred de 6–9, 9–15 et 15–30 kg.','ME, NE, protéines SID, lysine SID, phosphore digestible et calcium.','Référentiel DanBred; ne pas appliquer directement aux porcs locaux ou à d''autres génotypes.',true,'source_checked','SID = standardized ileal digestible; valeurs par kg d''aliment.'),
('DANBRED-GROWER-NUTRITION','Growers – Pigs from 30–60 kg','DanBred',null,'DanBred Pig Manual','https://danbred-manual.com/en/pig-finisher-manual/growers-pigs-from-30-60-kg/','International',ARRAY['pigs']::text[],'official_guide','Besoins par kg d''aliment pour porcs DanBred en croissance.','ME, NE, protéines SID, lysine SID, phosphore digestible et calcium.','Référentiel génétique DanBred; catégories de poids spécifiques au manuel.',true,'source_checked','SID = standardized ileal digestible.'),
('DANBRED-FINISHER-NUTRITION','Feeding and Growth Performance – Finishers','DanBred',null,'DanBred Pig Manual','https://danbred-manual.com/en/pig-finisher-manual/feeding-and-growth-performance/','International',ARRAY['pigs']::text[],'official_guide','Valeurs de référence de croissance-finition selon les catégories de poids du manuel DanBred.','ME, NE, protéines SID, lysine SID, phosphore digestible et calcium.','Référentiel DanBred; vérifier la tranche de poids et le programme choisi.',true,'source_checked','SID = standardized ileal digestible.'),
('ARSO-DARS-1831-2024-RABBIT-DRAFT','DARS 1831:2024 – Rabbit Feeds, Specification (Draft African Standard)','African Organisation for Standardisation (ARSO)',2024,'Committee Draft African Standard','https://www.tbs.go.tz/uploads/publications/en-1739352844-DARS%201831%202024%20Rabbit%20feeds%20Specification.pdf','Africa – draft standard',ARRAY['rabbits']::text[],'draft_standard','Projet de norme africaine sur les aliments pour lapins; exigences par croissance, entretien, gestation et lactation.','Énergie digestible, protéines, cellulose, lipides et minéraux; limites proposées pour contaminants.','Document explicitement marqué DRAFT; ne constitue ni une norme finale ni une réglementation camerounaise.',true,'draft','Afficher comme repère provisoire uniquement.'),
('NASEM-SWINE-2012','Nutrient Requirements of Swine, 11th Revised Edition','National Research Council / National Academies',2012,'NASEM monograph','https://nap.nationalacademies.org/catalog/13298/nutrient-requirements-of-swine-eleventh-revised-edition','North America / International reference',ARRAY['pigs']::text[],'scientific_standard','Référence scientifique des besoins nutritionnels des porcs selon poids, sexe et état physiologique.','Cadre énergétique, acides aminés digestibles et minéraux.','Référence générale nord-américaine; adapter aux génotypes, matières premières et conditions camerounaises.',true,'source_checked','Référence générale, pas une table spécifique aux porcs locaux.') on conflict (citation_key) do nothing;insert into public.feed_nutrient_definitions (code,name_fr,name_en,unit,basis,nutrient_group,energy_system,applicable_species,description) values ('dry_matter','Matière sèche','Dry matter','%','as_fed','proximate',null,ARRAY['broiler','layers','local_barred_layer','local_chicken','pigs','rabbits']::text[],'Fraction de matière sèche du produit brut.'),
