('manganese','Manganèse','Manganese','mg/kg','as_fed','mineral',null,ARRAY['rabbits']::text[],'Manganèse total.') on conflict (code) do update set name_fr=excluded.name_fr,name_en=excluded.name_en,unit=excluded.unit,basis=excluded.basis,nutrient_group=excluded.nutrient_group,energy_system=excluded.energy_system,applicable_species=excluded.applicable_species,description=excluded.description;insert into public.ingredients (slug,name,scientific_name,category,description,processing_notes,safety_notes,anti_nutritional_factors,region_notes,is_published,safety_limit_required) values ('sorghum-grain','Sorgho grain','Sorghum bicolor','Énergie','Grain de sorgho entier destiné à l''alimentation des monogastriques.','Nettoyer puis broyer; caractériser variété et couleur.','Les variétés riches en tanins peuvent réduire digestibilité et performances; rechercher moisissures et ergot.','Tanins condensés, phytates; risque HCN surtout dans jeunes repousses et parties végétatives.','Présent surtout dans les zones septentrionales; composition variable selon variété.',true,true),
('pearl-millet','Mil perlé','Pennisetum glaucum','Énergie','Grain de mil perlé utilisé comme source énergétique et protéique secondaire.','Nettoyage et broyage; contrôler granulométrie.','Variabilité élevée; vérifier qualité du grain et mycotoxines.','Phytates; tanins variables selon cultivar.','Disponibilité variable dans les zones de production du Nord et de l''Extrême-Nord.',true,true),
('cassava-roots-dried','Farine de racines de manioc séchées','Manihot esculenta','Énergie','Racines de manioc épluchées, séchées et broyées.','Épluchage, découpage et séchage complet; vérifier HCN résiduel.','Ne jamais utiliser de manioc amer insuffisamment détoxifié; faible teneur protéique.','Glycosides cyanogènes (linamarine, lotaustraline), phytates selon produit.','Disponible dans plusieurs régions; distinguer racine, pulpe et épluchures.',true,true),
('cassava-leaf-meal','Farine de feuilles de manioc','Manihot esculenta','Protéines / fibres','Feuilles de manioc séchées et broyées, riches en azote mais fibreuses.','Séchage ou ensilage avec contrôle du cyanure; analyser les fibres.','Incorporation prudente; profil déficitaire en acides aminés soufrés.','HCN, tanins, fibres et phytates.','Sous-produit de cultures vivrières; qualité dépend de l''âge des feuilles et du traitement.',true,true),
('sweet-potato-roots','Farine de patate douce','Ipomoea batatas','Énergie','Tubercules de patate douce séchés et broyés.','Traitement thermique possible pour améliorer digestibilité de l''amidon; sécher avant stockage.','Faible teneur protéique; équilibrer avec des sources protéiques.','Inhibiteurs de trypsine dans produits crus; amidon et sucres variables.','Disponibilité locale variable; distinguer tubercules crus, cuits et séchés.',true,true),
('sweet-potato-vines','Fanes de patate douce','Ipomoea batatas','Protéines / fibres','Feuilles et tiges de patate douce utilisées comme complément fibreux/protéique.','Hacher, sécher ou ensiler; analyser fibres et minéraux.','Ne pas substituer intégralement les sources protéiques concentrées.','Oxalates, phytates, tanins et inhibiteurs de protéases selon produit.','Sous-produit agricole local; composition dépend de la variété et du rapport feuilles/tiges.',true,true),
('cowpea-grain','Niébé grain','Vigna unguiculata','Protéines végétales','Grain de niébé destiné à l''alimentation animale après traitement adapté.','Cuisson, toastage ou autre traitement thermique contrôlé; éviter la graine crue.','Utilisation conditionnée par traitement et équilibre des acides aminés.','Inhibiteurs de trypsine, lectines, tanins et phytates selon cultivar.','Légumineuse cultivée au Cameroun; profils publiés surtout Afrique de l''Ouest et australe.',true,true),
('pigeon-pea-grain','Pois d''Angole','Cajanus cajan','Protéines végétales','Grain de pois d''Angole utilisé comme source protéique complémentaire.','Traitement thermique et contrôle des facteurs antinutritionnels.','Ne pas appliquer des taux d''essais isolés comme recommandations universelles.','Tanins, inhibiteurs de trypsine, phytates.','Disponibilité locale à confirmer selon bassins de production.',true,true),
('lablab-grain','Lablab','Lablab purpureus','Protéines végétales','Graines de lablab destinées à être utilisées après traitement.','Cuisson ou toastage validé; contrôler digestibilité et humidité.','Éviter la graine crue; formulation conditionnée par traitement et profil AA.','Tanins, inhibiteurs de trypsine et autres facteurs antinutritionnels.','Disponibilité variable; données surtout issues de recherches tropicales.',true,true),
('sunflower-meal','Tourteau de tournesol','Helianthus annuus','Protéines / fibres','Résidu d''extraction d''huile de graines de tournesol.','Documenter décorticage et méthode d''extraction; broyage homogène.','Lysine relativement limitante et fibre élevée surtout si non décortiqué.','Composés phénoliques; variabilité de fibre et protéines.','Disponibilité commerciale à vérifier au Cameroun; distinguer tourteau décortiqué/non décortiqué.',true,true),
('sesame-meal','Tourteau de sésame','Sesamum indicum','Protéines végétales','Résidu d''extraction d''huile de graines de sésame.','Documenter pression/extraction, huile résiduelle et décorticage.','Lysine limitante; attention aux coques et aux oxalates.','Oxalates, phytates et fibres selon décorticage.','Données nutritionnelles internationales disponibles; disponibilité locale à confirmer.',true,true),
('copra-meal','Tourteau de coprah','Cocos nucifera','Protéines / fibres','Résidu d''extraction d''huile de coprah.','Contrôler humidité, rancissement et contamination fongique.','Protéines et énergie variables; certains acides aminés peuvent limiter.','Fibres, rancissement et mycotoxines de stockage.','Disponibilité régionale à documenter selon circuits commerciaux.',true,true),
('black-soldier-fly-meal','Farine de larves de mouche soldat noire','Hermetia illucens','Protéines alternatives','Farine de larves de mouche soldat noire, entière ou dégraissée.','Tracer substrat, stade larvaire, séchage, dégraissage et qualité microbiologique.','Composition dépend du substrat et du dégraissage; vérifier biosécurité et réglementation.','Chitine, cendres/minéraux et contaminants possibles selon substrat.','Intérêt croissant au Cameroun; ne pas transposer une composition d''un substrat à un autre.',true,true) on conflict (slug) do update set name=excluded.name,scientific_name=excluded.scientific_name,category=excluded.category,description=excluded.description,processing_notes=excluded.processing_notes,safety_notes=excluded.safety_notes,anti_nutritional_factors=excluded.anti_nutritional_factors,region_notes=excluded.region_notes,is_published=excluded.is_published,safety_limit_required=excluded.safety_limit_required;with v(species,genotype,stage,nutrient_code,nutrient_name,min_value,max_value,unit,basis,requirement_basis,source_title,source_url,source_year,verified,evidence_level,notes,age_min_days,age_max_days,body_weight_min_kg,body_weight_max_kg,geography) as (values ('broiler','Ross 308 (>3,5 kg cible)','Démarrage','AMEn_broiler','Énergie AMEn',2975,2975,'kcal/kg','as_fed','per_kg_feed','Ross Broiler Nutrition Specifications 2022 – Table 3','https://eu.aviagen.com/assets/Tech_Center/Ross_Broiler/Ross-BroilerNutritionSpecifications2022-EN.pdf',2022,true,'official_breeder_guide','Guide officiel spécifique à la souche; respecter les âges et la cible de poids de la table.',0,10,null,null,'International'),
