('rabbits','generic','Lactation','manganese','Manganèse',2.5,null,'mg/kg','as_fed','per_kg_feed','DARS 1831:2024 – Rabbit Feeds (Draft African Standard)','https://www.tbs.go.tz/uploads/publications/en-1739352844-DARS%201831%202024%20Rabbit%20feeds%20Specification.pdf',2024,false,'draft_standard','Projet de norme africaine explicitement marqué DRAFT; repère provisoire, non adopté comme norme finale et non validé spécifiquement au Cameroun.',null,null,null,null,'International')) insert into public.species_requirements (species,genotype,stage,nutrient_code,nutrient_name,min_value,max_value,unit,basis,requirement_basis,source_title,source_url,source_year,verified,evidence_level,notes,age_min_days,age_max_days,body_weight_min_kg,body_weight_max_kg,geography,reviewed) select v.species,v.genotype,v.stage,v.nutrient_code,v.nutrient_name,v.min_value,v.max_value,v.unit,v.basis,v.requirement_basis,v.source_title,v.source_url,v.source_year,v.verified,v.evidence_level,v.notes,v.age_min_days,v.age_max_days,v.body_weight_min_kg,v.body_weight_max_kg,v.geography,true from v where not exists(select 1 from public.species_requirements x where x.species=v.species and x.genotype=v.genotype and x.stage=v.stage and x.nutrient_code=v.nutrient_code and x.source_title=v.source_title); update public.species_requirements set genotype='Poule barrée locale camerounaise',geography='Cameroon',evidence_level='local_experimental',reviewed=true where species='local_barred_layer' and source_year=2015;